print(json.dumps({"python": sys.version, "sdk": importlib.metadata.version("kaggle-benchmarks"), "node": shutil.which("node"), "models": sorted(kbench.llms.keys()), "defaultModel": getattr(kbench.llm, "name", None)}, indent=2))

